<?php
declare(strict_types=1);
$crmTitle='Promosi';
$search=trim((string)($_GET['q']??''));
$halaqoh=$_GET['halaqoh']??[]; if(!is_array($halaqoh))$halaqoh=$halaqoh!==''?[$halaqoh]:[];
$halaqoh=array_values(array_filter(array_map('trim',$halaqoh)));
$status=trim((string)($_GET['status']??'proses'));
$pembayaran=trim((string)($_GET['pembayaran']??''));
$halaqohList=[];$r=$conn->query("SELECT DISTINCT halaqoh FROM peserta WHERE halaqoh IS NOT NULL AND halaqoh<>'' ORDER BY halaqoh");
if($r)while($row=$r->fetch_assoc())$halaqohList[]=(string)$row['halaqoh'];
$where=["p.nowa IS NOT NULL","p.nowa<>''"];$params=[];$types='';
if($search!==''){$where[]="p.nama_lengkap LIKE ?";$params[]='%'.$search.'%';$types.='s';}
if($halaqoh){$ph=implode(',',array_fill(0,count($halaqoh),'?'));$where[]="p.halaqoh IN ($ph)";$params=array_merge($params,$halaqoh);$types.=str_repeat('s',count($halaqoh));}
if(in_array($status,['proses','selesai'],true)){$where[]="p.status=?";$params[]=$status;$types.='s';}
$sql="SELECT p.id,p.nama_lengkap,p.nowa,p.halaqoh,p.status,CASE WHEN MAX(pemb.id) IS NULL THEN 0 ELSE 1 END AS sudah_bayar FROM peserta p LEFT JOIN pembayaran pemb ON p.id=pemb.peserta_id WHERE ".implode(' AND ',$where)." GROUP BY p.id,p.nama_lengkap,p.nowa,p.halaqoh,p.status";
if($pembayaran==='lunas')$sql.=" HAVING sudah_bayar=1";elseif($pembayaran==='belum_lunas')$sql.=" HAVING sudah_bayar=0";
$sql.=" ORDER BY CASE WHEN UPPER(TRIM(p.halaqoh)) LIKE 'AK%' THEN 1 WHEN UPPER(TRIM(p.halaqoh)) LIKE 'IK%' THEN 2 ELSE 3 END, CAST(SUBSTRING(TRIM(p.halaqoh),3) AS UNSIGNED), p.halaqoh, p.nama_lengkap LIMIT 200";
$peserta=[];$stmt=$conn->prepare($sql);
if($stmt){if($params){$refs=[];foreach($params as $k=>$v)$refs[$k]=&$params[$k];call_user_func_array([$stmt,'bind_param'],array_merge([$types],$refs));}$stmt->execute();$peserta=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt->close();}
$previousMessages=[];$r=$conn->query("SELECT message,COUNT(*) usage_count,MAX(sent_at) last_used_at FROM crm_message_history WHERE template_name='Promosi' AND status='sent' AND message<>'' GROUP BY message ORDER BY last_used_at DESC LIMIT 20");
if($r)while($row=$r->fetch_assoc())$previousMessages[]=$row;
function promosiTime(string $v):string{$t=strtotime($v);return $t?date('d M Y, H:i',$t):'-';}
?>
